import{_ as o,o as t,c as d,a2 as a}from"./chunks/framework.Dxeykp0S.js";const p=JSON.parse('{"title":"Day 1 · 面向对象：class 与魔术方法","description":"","frontmatter":{},"headers":[],"relativePath":"basic/01-oop.md","filePath":"basic/01-oop.md","lastUpdated":1787141678000}'),c={name:"basic/01-oop.md"};function r(l,e,i,s,n,h){return t(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="day-1-·-面向对象-class-与魔术方法" tabindex="-1">Day 1 · 面向对象：class 与魔术方法 <a class="header-anchor" href="#day-1-·-面向对象-class-与魔术方法" aria-label="Permalink to &quot;Day 1 · 面向对象：class 与魔术方法&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>你从 ES6 class 过来，会觉得 Python 的 class 似曾相识，但很快就会发现：Python 的 OOP 更&quot;裸露&quot;——没有真正的私有、一切皆协议、魔术方法（dunder method）控制着对象的一切行为。理解了魔术方法，你就理解了 Python 的设计哲学：<strong>数据模型优于语法糖</strong>。</p><h2 id="课程目标" tabindex="-1">课程目标 <a class="header-anchor" href="#课程目标" aria-label="Permalink to &quot;课程目标&quot;">​</a></h2><ul><li>掌握 class 定义、继承、<code>super()</code></li><li>掌握常用魔术方法：<code>__init__</code> <code>__repr__</code> <code>__eq__</code> <code>__len__</code> <code>__getitem__</code> 等</li><li>熟练使用 <code>@property</code>、<code>@staticmethod</code>、<code>@classmethod</code></li><li>使用 <code>@dataclass</code> 消灭样板代码</li></ul><h2 id="阅读学习" tabindex="-1">阅读学习 <a class="header-anchor" href="#阅读学习" aria-label="Permalink to &quot;阅读学习&quot;">​</a></h2><ul><li><a href="https://docs.python.org/zh-cn/3/tutorial/classes.html" target="_blank" rel="noreferrer">Python 官方教程第 9 章：类</a></li><li><a href="https://docs.python.org/zh-cn/3/reference/datamodel.html" target="_blank" rel="noreferrer">Python 数据模型（魔术方法大全）</a>（浏览）</li><li>对照速览：</li></ul><table tabindex="0"><thead><tr><th>JS</th><th>Python</th></tr></thead><tbody><tr><td><code>constructor()</code></td><td><code>__init__(self)</code>（self 必须显式声明）</td></tr><tr><td><code>this</code></td><td><code>self</code>（约定名，不是关键字）</td></tr><tr><td><code>toString()</code></td><td><code>__str__</code> / <code>__repr__</code></td></tr><tr><td><code>obj[key]</code></td><td><code>__getitem__</code> / <code>__setitem__</code></td></tr><tr><td>getter/setter</td><td><code>@property</code> / <code>@x.setter</code></td></tr><tr><td>私有 <code>#field</code></td><td><code>_field</code>（约定）/ <code>__field</code>（名称改写，仍可访问）</td></tr><tr><td><code>instanceof</code></td><td><code>isinstance()</code></td></tr><tr><td>静态方法</td><td><code>@staticmethod</code></td></tr><tr><td>—</td><td><code>@classmethod</code>（接收 cls，常用于工厂方法）</td></tr></tbody></table><h2 id="任务作业" tabindex="-1">任务作业 <a class="header-anchor" href="#任务作业" aria-label="Permalink to &quot;任务作业&quot;">​</a></h2><ol><li><p><strong>实现一个&quot;像列表&quot;的类</strong>：写一个 <code>Stack</code> 类，支持 <code>len(s)</code>、<code>s[i]</code>、<code>for x in s</code>、<code>x in s</code>、<code>print(s)</code>，全部通过魔术方法实现。体会&quot;实现协议即融入语言&quot;。</p></li><li><p><strong>dataclass 实战</strong>：用 <code>@dataclass</code> 建模一个 <code>User</code>（含 name/email/age），要求：</p><ul><li><code>age</code> 有默认值 0</li><li>email 用 <code>__post_init__</code> 做格式校验</li><li>用 <code>field(compare=False)</code> 让排序只按 age</li><li>尝试 <code>frozen=True</code> 体会不可变 dataclass</li></ul><p>然后反思：这个装饰器帮你省掉了哪些样板代码？</p></li><li><p><strong>property 重构</strong>：把一个暴露公共属性 <code>celsius</code> 的 <code>Temperature</code> 类，重构成不破坏调用方代码的 <code>@property</code> 版本（访问 <code>.celsius</code> 时动态计算自内部存储的开尔文值）。体会 Python 的&quot;先公开、后属性化&quot;重构自由。</p></li><li><p><strong>classmethod 工厂</strong>：给 <code>User</code> 增加 <code>User.from_dict(data)</code> 和 <code>User.from_json(s)</code> 两个工厂方法，用 <code>@classmethod</code> 实现。</p></li></ol><h2 id="自测问题" tabindex="-1">自测问题 <a class="header-anchor" href="#自测问题" aria-label="Permalink to &quot;自测问题&quot;">​</a></h2><ul><li><code>__str__</code> 和 <code>__repr__</code> 的区别是什么？只实现一个的话实现哪个？</li><li>Python 的 <code>__private</code> 双下划线属性真的私有吗？它是如何实现的（name mangling）？</li><li>Python 支持多继承，<code>super()</code> 的查找顺序遵循什么算法（MRO）？</li><li>dataclass 的 <code>eq=True</code>、<code>order=True</code>、<code>frozen=True</code> 分别生成哪些方法？</li><li>为什么 Python 的实例方法要显式接收 <code>self</code>？调用时它是如何传入的？</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>记录今天的学习笔记。</p><h2 id="拓展阅读" tabindex="-1">拓展阅读 <a class="header-anchor" href="#拓展阅读" aria-label="Permalink to &quot;拓展阅读&quot;">​</a></h2><ul><li><a href="https://www.oreilly.com/library/view/fluent-python-2nd/9781492056348/" target="_blank" rel="noreferrer">《Python 之禅》与数据模型：Luciano Ramalho 的 Fluent Python 第 1 章（经典）</a></li></ul><h2 id="预告" tabindex="-1">预告 <a class="header-anchor" href="#预告" aria-label="Permalink to &quot;预告&quot;">​</a></h2><p>下一节学习<a href="./02-iterators-generators">迭代器与生成器</a>：<code>yield</code> 是 Python 并发和流式处理的基石。</p>',18)])])}const u=o(c,[["render",r]]);export{p as __pageData,u as default};
